@push('scripts')<script>(function(){function decode(v){const b=Uint8Array.from(atob(v),c=>c.charCodeAt(0));return JSON.parse(new TextDecoder().decode(b));}document.querySelectorAll('.js-faculty-edit').forEach(b=>b.addEventListener('click',()=>{const r=decode(b.dataset.record);[['faculty-edit-id','id'],['faculty-edit-code','code'],['faculty-edit-no','no'],['faculty-edit-title','title'],['faculty-edit-college','college'],['faculty-edit-status','status']].forEach(([i,k])=>document.getElementById(i).value=r[k]??'');}));document.querySelectorAll('.js-entity-delete').forEach(b=>b.addEventListener('click',()=>{document.getElementById('entity-delete-id').value=b.dataset.id;document.getElementById('entity-delete-title').textContent=b.dataset.title;document.getElementById('entity-delete-form').action=b.dataset.action;}));})();</script>@endpush
